class FormalMethodDefinition(Strict):
    contract: Literal["knowlab/formal-method/v1"]
    capability_declaration: CapabilityDeclaration
    access_requirements: tuple[AccessRequirement, ...] = Field(max_length=100)
    procedure: Annotated[ToolProcedure | Orchestration, Field(discriminator="kind")]
    how_to_validate: tuple[ValidationRule, ...] = Field(min_length=1, max_length=100)
    what_requires_approval: tuple[ApprovalRule, ...] = Field(max_length=100)

    @model_validator(mode="after")
    def valid(self):
        requirements = {r.requirement_id: r for r in self.access_requirements}
        if len(requirements) != len(self.access_requirements):
            raise ValueError("Duplicate permission requirement")
        if set(self.capability_declaration.promises) != {
            r.promise_id for r in self.how_to_validate
        }:
            raise ValueError(
                "Every promise needs validation and every validation needs a promise"
            )
        for rule in self.what_requires_approval:
            requirement = requirements.get(rule.requirement_id)
            if requirement is None or not set(rule.operations) <= set(
                requirement.operations
            ):
                raise ValueError("Approval must refer to declared business operations")
        if isinstance(self.procedure, ToolProcedure):
            refs = self.procedure.implementation.requirement_ids
            if len(refs) != len(set(refs)) or set(refs) != requirements.keys():
                raise ValueError(
                    "The direct implementation must bind its declared permissions"
                )
        else:
            for step in self.procedure.steps:
                for inp in step.inputs.values():
                    if isinstance(inp.binding, ResourceValue):
                        requirement = requirements.get(inp.binding.requirement_id)
                        if requirement is None or inp.binding.role not in {
                            r.resource_role for r in requirement.resources
                        }:
                            raise ValueError(
                                "Resource input must name a declared permission role"
                            )
        views = self.interfaces()  # Also detects conflicting external names.
        for condition in self.capability_declaration.conditions.values():
            slots = set(condition.input_slots)
            if (
                len(slots) != len(condition.input_slots)
                or slots - views["inputs"].keys()
            ):
                raise ValueError(
                    "Condition inputs must name distinct public input slots"
                )
        for rule in self.how_to_validate:
            if not set(rule.outputs) <= views["outputs"].keys():
                raise ValueError("Validation must name generated public outputs")
        return self

    def interfaces(self) -> dict[str, Any]:
        if isinstance(self.procedure, ToolProcedure):
            return {
                "inputs": {
                    k: {
                        "slot": v.model_dump(mode="json", by_alias=True),
                        "required_by": ["implementation"] if v.required else [],
                    }
                    for k, v in self.procedure.inputs.items()
                },
                "outputs": {
                    k: {
                        "slot": v.model_dump(mode="json", by_alias=True),
                        "always_present": v.required,
                    }
                    for k, v in self.procedure.outputs.items()
                },
            }
        inputs: dict[str, Any] = {}
        for step in self.procedure.steps:
            for item in step.inputs.values():
                if not isinstance(item.binding, (CallerValue, ObjectItem)):
                    continue
                key = item.binding.name
                slot = item.slot.model_dump(mode="json", by_alias=True)
                if isinstance(item.binding, ObjectItem):
                    assert self.procedure.object_batch is not None
                    slot["schema"] = {
                        "type": "array",
                        "minItems": 1,
                        "maxItems": self.procedure.object_batch.max_objects,
                        "uniqueItems": True,
                        "items": {"type": "string", "minLength": 1},
                    }
                if key in inputs and inputs[key]["slot"] != slot:
                    raise ValueError(
                        "External aliases cannot merge different meanings or shapes"
                    )
                entry = inputs.setdefault(
                    key, {"slot": slot, "required_by": [], "used_by": []}
                )
                entry["used_by"].append(step.id)
                if item.slot.required and step.always_required:
                    entry["required_by"].append(step.id)
        steps = {s.id: s for s in self.procedure.steps}
        return {
            "inputs": inputs,
            "outputs": {
                name: {
                    "slot": steps[ref.step]
                    .outputs[ref.output]
                    .model_dump(mode="json", by_alias=True),
                    "always_present": ref.always_present,
                }
                for name, ref in self.procedure.exports.items()
            },
        }

    def document(self) -> dict[str, Any]:
        return self.model_dump(mode="json", by_alias=True)

    def digest(self) -> str:
        return (
            "sha256:"
            + hashlib.sha256(
                json.dumps(
                    self.document(),
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                    allow_nan=False,
                ).encode()
            ).hexdigest()
        )
